import{_ as e,c as t,o as a,a4 as p}from"./chunks/framework.DzOtv0XR.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"economics/concept.md","filePath":"economics/concept.md"}'),n={name:"economics/concept.md"},c=p('<h2 id="夏普比" tabindex="-1">夏普比 <a class="header-anchor" href="#夏普比" aria-label="Permalink to &quot;夏普比&quot;">​</a></h2><p>夏普比率描述了资产收益对投资者所承担<strong>风险的补偿</strong>程度。</p><p>获胜概率 * 收益比例</p><p>收益要足够大，值得冒险</p><p>50% * 2 = 1 // 不赚不赔 90% * 0.1 = 0.99 10% * 100 = 10 // 大于 10 倍就划算</p><h2 id="缩表" tabindex="-1">缩表 <a class="header-anchor" href="#缩表" aria-label="Permalink to &quot;缩表&quot;">​</a></h2><p>缩表，缩的是“资产负债表”</p><p>纸币其实就是一种债权证明，是一张特殊的欠条，是央行的负债。所以央行的缩表要减少负债，这就相当于收回纸币，不再流通。</p><p>美联储通过缩表，调节基础货币数量，是退出宽松措施的一种举措，属于紧缩政策。</p><p>钱少了，整个市场利率又上升了，那么股市会出现一定程度的下跌预期。</p><p>最近十年，日本继续走向全球化，但经济却内卷化；全球经济效仿日本，亦日益内卷化。</p><p><img src="https://img.oaker.bid/?url=http://tva1.sinaimg.cn/mw690/4e5d3ea7ly1hbk2bt3evij20k00a0weo.jpg" alt="42B98C76-FE93-47B2-90BD-087AAC3ED03E.jpg"></p><p>22年来最大加息，到底啥是美联储缩表？_手机新浪网 <a href="https://finance.sina.cn/2022-05-05/detail-imcwiwst5681670.d.html" target="_blank" rel="noreferrer">https://finance.sina.cn/2022-05-05/detail-imcwiwst5681670.d.html</a></p><p>2020年受新冠疫情冲击，美联储将联邦基金利率降到零，直接采购债券ETF和企业债，向日本化迈出了实际性一步。美国、英国、加拿大及欧洲的央行资产负债表大幅度扩张，政府债务也大规模上升。</p><p>日本率先探索了一条量化宽松+负利率的危机管理模式，形成一种兜底式惯性思维：有困难找政府。全球主要国家都在效仿日本，当经济衰退时，政府加杠杆，以维持高福利。</p><p>现代货币理论推崇日本模式，认为只要汇率、通胀率平稳，央行可以为政府提供融资（债券等同于货币），以应对衰退与危机。</p><p><a href="http://www.china-cer.com.cn/shijiejingji/202006266102.html" target="_blank" rel="noreferrer">为什么说全球经济正加速“日本化”</a></p>',17),r=[c];function o(i,s,_,h,l,d){return a(),t("div",null,r)}const g=e(n,[["render",o]]);export{f as __pageData,g as default};
